cssHead:
body {
  background-color: #F9FAF7;
  font-family: 'Geist', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #203E35;
  -webkit-font-smoothing: antialiased;
}
.sphere-orb {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #A9C2B0 0%, #708F79 50%, #4D6D56 85%, #344C3B 100%);
  box-shadow: 0 2px 6px rgba(32, 62, 53, 0.18), inset 0 1px 2px rgba(255, 255, 255, 0.45);
}
